import{H as e,ht as t,nt as n,tt as r}from"./chunks/framework.CXX_0q1Z.js";var i=JSON.parse(`{"title":"动作管道性能说明","description":"","frontmatter":{},"headers":[],"relativePath":"modules/corelib/action-performance.md","filePath":"modules/corelib/action-performance.md","lastUpdated":0}`),a={name:`modules/corelib/action-performance.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<h1 id="动作管道性能说明" tabindex="-1">动作管道性能说明 <a class="header-anchor" href="#动作管道性能说明" aria-label="Permalink to “动作管道性能说明”">​</a></h1><p>本页是 Emaki 动作管道的性能口径: 可静态证实的架构优势, 可复现的基准方法, 以及量化结果表.<strong>本环境无 Paper/Folia 实机, 量化项一律标注&quot;未执行&quot;并给出关闭条件</strong> -- 架构优势可被源码证实, 具体数字必须由实机测得后才能对外引用</p><h2 id="架构优势-源码可证实" tabindex="-1">架构优势 (源码可证实) <a class="header-anchor" href="#架构优势-源码可证实" aria-label="Permalink to “架构优势 (源码可证实)”">​</a></h2><h3 id="_1-编译期固化-运行期零解析" tabindex="-1">1. 编译期固化, 运行期零解析 <a class="header-anchor" href="#_1-编译期固化-运行期零解析" aria-label="Permalink to “1. 编译期固化, 运行期零解析”">​</a></h3><p>管道在配置加载期经 <code>PipelineParser</code> + <code>StaticValidator</code> 一次性编译为 <code>CompiledPipeline</code> (AST + 类型化参数校验通过). 运行期 <code>ActionInterpreter</code> 直接执行已编译结构:</p><ul><li>不做字符串重新分词, 不做参数类型校验, 不做未知段查找;</li><li>参数渲染只对含占位符的值执行 <code>render</code>, 纯字面量跳过;</li><li>编译失败在加载期报出全部诊断 (48+ 项规则), 运行期不存在&quot;写错段名才发现&quot;的路径</li></ul><h3 id="_2-gate-短路与分组调度" tabindex="-1">2. gate 短路与分组调度 <a class="header-anchor" href="#_2-gate-短路与分组调度" aria-label="Permalink to “2. gate 短路与分组调度”">​</a></h3><ul><li><strong>gate 短路</strong>: 源段 <code>Empty</code>, gate <code>Halted</code> 直接进入终态 (<code>stopped</code>), 后续段整段跳过, 不做任何跨域调度;</li><li><strong>同域合批</strong>: <code>StageGroup</code> 把连续的同域段合为一次调度 (<code>foldable</code> 段可附加到前组), 减少 Folia/Paper 线程切换次数 -- 例如&quot;改背包 + 改经验值&quot;两个 <code>CONTEXT_ENTITY</code> 段只发生一次 owner 线程转移;</li><li><strong>五域分级</strong>: <code>SERVER_GLOBAL</code> / <code>CONTEXT_ENTITY</code> / <code>LOCATION_REGION</code> / <code>ASYNC_COMPUTE</code> / <code>UNDECLARED</code> 在注册期强制声明 (<code>StageRegistry.checkDomain</code>), 运行期 <code>StageDispatcher</code> 按域分发.<strong>竞品普遍没有线程域分级</strong>, 这是 Emaki 在 Folia 上的结构性差异</li></ul><h3 id="_3-热路径零分配观测" tabindex="-1">3. 热路径零分配观测 <a class="header-anchor" href="#_3-热路径零分配观测" aria-label="Permalink to “3. 热路径零分配观测”">​</a></h3><p><code>StepReporter</code> 默认实现为 <code>NOOP</code> (接口空方法), 非调试运行时所有观测点为空调用; <code>ActionAuditLogger</code> 无 <code>DebugLogger</code> 时直接返回. 观测基础设施不给生产热路径带来分配或分支成本</p><h3 id="_4-淘汰优先于执行" tabindex="-1">4. 淘汰优先于执行 <a class="header-anchor" href="#_4-淘汰优先于执行" aria-label="Permalink to “4. 淘汰优先于执行”">​</a></h3><p>每级 gate 的输入/输出计数在 <code>StepReporter.gate</code> 上报 (干跑/调试模式渲染漏斗); 语义上&quot;先筛后打&quot; -- <code>filter</code>/<code>where</code> 在动作执行前淘汰不合格目标, 避免对无效目标做跨域调度</p><h2 id="基准方法-可复现" tabindex="-1">基准方法 (可复现) <a class="header-anchor" href="#基准方法-可复现" aria-label="Permalink to “基准方法 (可复现)”">​</a></h2><p>沿用 <code>.spigot-dev/guides/performance-baseline.md</code> 的采样纪律: 同一场景, 同一时长, 同一规模才可对比. 三个必测场景:</p><table tabindex="0"><thead><tr><th>场景</th><th>测什么</th><th>怎么触发</th><th>预算目标</th></tr></thead><tbody><tr><td>管道吞吐</td><td>每秒完成的管道执行数</td><td><code>execute</code> 模式连续跑固定短管道 (如 <code>self | damage amount=1</code>), spark 采样 120s</td><td>待实机基线后填写</td></tr><tr><td>P95 延迟</td><td>单条管道的端到端延迟分布</td><td>同上, <code>/spark profiler</code> 方法级采样 <code>ActionInterpreter.walk</code></td><td>待实机基线后填写</td></tr><tr><td>gate 短路收益</td><td><code>Halted</code>/<code>Empty</code> 路径 vs 全通过路径的耗时差</td><td>对比 <code>filter &#39;health_percent&lt;=0&#39;</code> (必然全淘汰) 与 <code>filter &#39;health_percent&lt;=100&#39;</code> (必然全通过)</td><td>短路路径应显著低于全通过路径</td></tr></tbody></table><p>观测命令:</p><div class="language-"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>/spark profiler start --timeout 120</span></span>
<span class="line"><span># 跑固定场景...</span></span>
<span class="line"><span>/spark profiler stop --save-to-file</span></span></code></pre></div><p>关分组调度收益: 在 spark 方法级采样中对比 <code>StageDispatcher.dispatch</code> 的调用次数与被调度段数之比 -- 合批生效时该比值应明显小于 1</p><h2 id="量化结果" tabindex="-1">量化结果 <a class="header-anchor" href="#量化结果" aria-label="Permalink to “量化结果”">​</a></h2><table tabindex="0"><thead><tr><th>指标</th><th>数值</th><th>采集日期</th><th>状态</th></tr></thead><tbody><tr><td>管道吞吐 (条/秒)</td><td>—</td><td>—</td><td><strong>未执行</strong></td></tr><tr><td>P95 端到端延迟</td><td>—</td><td>—</td><td><strong>未执行</strong></td></tr><tr><td>gate 短路收益 (短路 vs 全通过)</td><td>—</td><td>—</td><td><strong>未执行</strong></td></tr><tr><td>合批后 dispatch 次数/段数比</td><td>—</td><td>—</td><td><strong>未执行</strong></td></tr></tbody></table><p><strong>关闭条件</strong>: Paper 1.21.8 实机按上表三场景各跑一轮 spark 采样, 把数值填回本表并标注采集日期; 在此之前本页任何量化格都不得填入推测值</p><h2 id="与竞品的对比口径" tabindex="-1">与竞品的对比口径 <a class="header-anchor" href="#与竞品的对比口径" aria-label="Permalink to “与竞品的对比口径”">​</a></h2><ul><li><strong>可静态引用</strong> (源码级事实): 五域线程分组与 Folia 域强制声明 (MythicMobs/Skript 无此机制); 编译期 48+ 项诊断 (MythicMobs 靠运行期报错 + Wiki 猜测)</li><li><strong>不可引用</strong> (需实机): 任何吞吐, 延迟, TPS 数字. 竞品侧数字同样是营销口径, 对外引用前须复检来源日期</li></ul>`,23)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};